"""The glue between your simulator and the store. Given: you do not edit this file.

A run is described by DATA, a Plan, so it can be generated, saved, printed and shrunk:

    Plan(ops, faults)
      op    = (client, start, f, key, value, node)
                 client  0, 1, 2, ...: each client does its ops one after another, in list order
                 start   earliest simulated time to begin (it waits if its previous op is still pending)
                 f       "read" or "write";  value: the value to write (None for a read)
                 node    which server (0, 1 or 2) coordinates this request
      fault = (time, kind, arg)
                 (t, "crash", node)   (t, "restart", node)
                 (t, "partition", ((0,), (1, 2)))   groups cut off from each other      (t, "heal", None)

`run_plan` builds a simulator, adds the three store nodes and the clients, schedules the faults,
runs to the end, and calls your Recorder as clients invoke and get answers.
"""
from collections import namedtuple

Plan = namedtuple("Plan", "ops faults")
RunResult = namedtuple("RunResult", "seed ok reason trace_hash plan trace operations")
NetConfig = namedtuple("NetConfig", "min_delay max_delay drop dup")

DEFAULT_NET = NetConfig(min_delay=1, max_delay=8, drop=0.05, dup=0.05)
CLIENT_TIMEOUT = 150            # a client gives up on a request after this many ticks
HORIZON = 4000                  # the run stops here even if timers are still pending
SERVERS = (0, 1, 2)


class InvariantViolation(Exception):
    """Raised by run_plan as soon as an invariant function returns a message. `.sim` is the simulator."""


def plan_items(plan):
    """A plan as one flat list of items, so a shrinker can drop any of them."""
    return [("op", o) for o in plan.ops] + [("fault", f) for f in plan.faults]


def plan_from_items(items):
    ops = tuple(o for kind, o in items if kind == "op")
    faults = tuple(sorted((o for kind, o in items if kind == "fault"), key=lambda f: (f[0], f[1], str(f[2]))))
    return Plan(ops, faults)


class ClientNode:
    """One client. It sits on the simulated network (id 100 + index) and never crashes."""

    def __init__(self, node_id, sim, index, ops, recorder):
        self.id, self.sim, self.index, self.ops, self.recorder = node_id, sim, index, ops, recorder
        self.next = 0               # index of the next op to start
        self.generation = 0         # bumped after a timeout: the old request may still be in flight
        self.pending = None         # (request id, f, value) or None

    def on_start(self):
        self._schedule_next()

    def _schedule_next(self):
        if self.next < len(self.ops):
            start = self.ops[self.next][1]
            self.sim.schedule(max(0, start - self.sim.now), self._begin)

    def _begin(self):
        _, _, f, key, value, node = self.ops[self.next]
        self.next += 1
        rid = self.index * 1000 + self.next
        process = f"c{self.index}.{self.generation}"
        self.recorder.invoke(process, f, key, value, self.sim.now)
        self.pending = (rid, f, value, process)
        msg = ("client_write", rid, key, value) if f == "write" else ("client_read", rid, key)
        self.sim.send(self.id, node, msg)
        self.sim.set_timer(self.id, CLIENT_TIMEOUT, ("timeout", rid))

    def on_message(self, src, msg):
        if msg[0] != "client_ok" or self.pending is None or self.pending[0] != msg[1]:
            return                  # a late or duplicate answer
        _, f, value, process = self.pending
        self.pending = None
        self.recorder.ok(process, msg[2] if f == "read" else value, self.sim.now)
        self._schedule_next()

    def on_timer(self, tag):
        if tag[0] == "timeout" and self.pending is not None and self.pending[0] == tag[1]:
            process = self.pending[3]
            self.pending = None
            self.generation += 1
            self.recorder.info(process, self.sim.now)
            self._schedule_next()


def run_plan(plan, seed, *, simulator_cls, node_factory, recorder, invariants=()):
    """Run `plan` once. Returns the simulator. If an invariant function returns a message, raises
    InvariantViolation (with `.sim` set) immediately, in the middle of the run."""
    sim = simulator_cls(seed, DEFAULT_NET)
    for n in SERVERS:
        sim.add_node(n, node_factory)
    by_client = {}
    for op in plan.ops:
        by_client.setdefault(op[0], []).append(op)
    for c in sorted(by_client):
        sim.add_node(100 + c, lambda nid, s, d, c=c: ClientNode(nid, s, c, by_client[c], recorder), client=True)
    for t, kind, arg in plan.faults:
        if kind == "crash":
            sim.schedule(t, lambda a=arg: sim.crash(a))
        elif kind == "restart":
            sim.schedule(t, lambda a=arg: sim.restart(a))
        elif kind == "partition":
            sim.schedule(t, lambda a=arg: sim.partition(*a))
        elif kind == "heal":
            sim.schedule(t, sim.heal)

    def after_event():
        for inv in invariants:
            message = inv(sim)
            if message:
                err = InvariantViolation(f"{inv.__name__}: {message} (t={sim.now})")
                err.sim = sim
                raise err

    sim.run(HORIZON, after_event=after_event if invariants else None)
    return sim
